import{_ as t,o,c as a,a2 as n}from"./chunks/framework.doxMM-x8.js";const u=JSON.parse('{"title":"Development And Validation","description":"","frontmatter":{"docLocale":"en","counterpart":"/testing/feedback-loop","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/testing/feedback-loop.md","filePath":"en/testing/feedback-loop.md"}'),r={name:"en/testing/feedback-loop.md"};function d(i,e,s,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="development-and-validation" tabindex="-1">Development And Validation <a class="header-anchor" href="#development-and-validation" aria-label="Permalink to &quot;Development And Validation&quot;">​</a></h1><p>Goal: select public checks that observe your Lab Word change. Run from the repository root. The <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/docs/testing/strategy.md" target="_blank" rel="noreferrer">testing strategy</a>defines responsibilities.</p><h2 id="choose-an-entry" tabindex="-1">Choose An Entry <a class="header-anchor" href="#choose-an-entry" aria-label="Permalink to &quot;Choose An Entry&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Change</th><th>Command</th><th>Evidence and prerequisites</th></tr></thead><tbody><tr><td>Web behavior</td><td><code>pnpm test:frontend</code></td><td>Real component interaction; HTTP uses MSW; motion golden checks need Python 3</td></tr><tr><td>TypeScript and boundaries</td><td><code>pnpm typecheck</code>, <code>pnpm boundaries:check</code></td><td>Types, package dependencies, Node module, qualified table and SDK ownership</td></tr><tr><td>Backend behavior</td><td><code>pnpm test:server</code></td><td>Real Node HTTP/CLI and isolated embedded data</td></tr><tr><td>Contracts</td><td><code>pnpm generate</code>, <code>pnpm contracts:check</code></td><td>Node OpenAPI, official generated types and SDK agree</td></tr><tr><td>Documentation</td><td><code>pnpm docs:check</code>, <code>pnpm docs:build</code></td><td>Sources, locale pairing, Node references and built links</td></tr><tr><td>Documentation browser journeys</td><td><code>pnpm test:e2e:docs</code></td><td>Language, theme, search, agreed viewports, custom base; requires Chromium</td></tr><tr><td>Critical application journeys</td><td><code>pnpm test:e2e</code></td><td>Owned Node/Web and real Chromium/WebGL; motion smoke needs the pinned Python environment</td></tr></tbody></table><p>Install Chromium with <code>pnpm exec playwright install chromium</code>. Default <code>pnpm test:e2e</code> also needs an isolated Python environment with the pinned tracked requirements. Follow <a href="./../tutorials/synthetic-motion#start-the-python-publisher">the synthetic motion setup</a>. The runner uses <code>.scratch/motion-python/bin/python</code> by default. Set <code>MOTION_E2E_PYTHON</code> to override its executable path.</p><p>The default suite runs motion smoke. It does not run the full motion acceptance of at least 600 seconds. See <a href="./../tutorials/synthetic-motion#verify-the-source">source verification</a> for exact commands and coverage. <code>pnpm check</code> runs current Node, formatting, static, behavior, budget and build checks without browser E2E. Its TS/Python golden checks require Python 3; set <code>PYTHON</code> to override the interpreter. Normal Node/Web startup and builds remain Python-independent.</p><p>Command capabilities do not expand task scope. Validate desktop web by default; include mobile adaptation, narrow screens, touch or real devices only within explicitly approved scope. Check discovery and prerequisites before heavy browser runs. Reuse existing critical journeys; use focused cases for affected CSS or layout states.</p><p><code>docs:check</code> and <code>docs:build</code> read the official Node OpenAPI and current configuration parser. <code>pnpm test:e2e</code> uses the owned Linux Node/Web browser supervisor. CI uses <code>pnpm check</code>, with complete cheap frontend/tooling checks before long server/contract suites. Keep actual browser prerequisites and task scope explicit.</p><h2 id="lab-viewer-boundaries" tabindex="-1">Lab Viewer Boundaries <a class="header-anchor" href="#lab-viewer-boundaries" aria-label="Permalink to &quot;Lab Viewer Boundaries&quot;">​</a></h2><p>The production Viewer and persistent World use the accepted <a href="./../guides/lab-viewer">Lab experience</a>. Retained browser journeys verify real GLB/HDR/WebGL, selection, drafts, devices and recovery.</p><p>Production component checks will observe import controls, selection, loading/error and recovery. Browser checks will observe real GLB/HDR, canvas pixels, camera and resource disposal. DOM success does not prove visible 3D rendering; one memory sample does not establish a leak.</p><p>On the first load of a World with models or an asset viewer, browser checks use <code>expectInitialSceneReady</code> to wait up to 15 seconds, then retain the actual model, pixel and error checks. The <a href="https://github.com/CaiZongyuan/labworld/actions/runs/38074047499" target="_blank" rel="noreferrer">actual GitHub Ubuntu/SwiftShader diagnosis</a> observed the correct 20-model scene after 9.269 seconds; the original five-second failure remains recorded. This test-environment wait applies only to the initial scene. Product performance promises, later action and recovery waits, the 600-second motion acceptance and count budgets remain unchanged.</p><h2 id="failure-and-evidence" tabindex="-1">Failure And Evidence <a class="header-anchor" href="#failure-and-evidence" aria-label="Permalink to &quot;Failure And Evidence&quot;">​</a></h2><p>Record commands, missing prerequisites and unverified scope when Docker, Chromium or dependencies are unavailable. Skipped checks are not passes. Backend checks use isolated resources and do not clean development or production data.</p><p>Record evidence against a fixed revision, environment and task scope. Reuse genuine TDD red and recovery green as VDD evidence for the same assertion. Local focused checks and one full gate in the responsible environment cover the stable final candidate. Reuse included affected checks. Refresh coverage by semantic impact after repairs or main changes. The <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/docs/agents/development-flow.md" target="_blank" rel="noreferrer">development flow</a> defines the sequence and independent review.</p><p>Use <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/.agents/skills/development-timeline/SKILL.md" target="_blank" rel="noreferrer">development-timeline</a> for lightweight stage, wait and rework records during multi-stage collaboration. Reports explain recorded progress and uncertainty; they do not add product validation or merge gates.</p><hr><p>Source version：<code>d21b97585cfd</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/docs/testing/t01-feedback-loop.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>',18)])])}const b=t(r,[["render",d]]);export{u as __pageData,b as default};
